from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def purge_expired(t):
        # remove all entries that have expired by time t
        expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            purge_expired(t)
            if key in cache:
                # update value and write time, move to end (most recently used)
                del cache[key]
                cache[key] = (value, t)
            else:
                if len(cache) >= capacity:
                    # evict least recently used (first item)
                    cache.popitem(last=False)
                cache[key] = (value, t)
        elif op[0] == 'get':
            _, t, key = op
            purge_expired(t)
            if key in cache:
                value, wt = cache[key]
                # move to end (most recently used)
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                results.append(-1)

    return results

